SELECT molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles, drug_indication.efo_id AS indication_curie, drug_indication.efo_term AS indication_label, drug_indication.max_phase_for_ind FROM molecule_dictionary INNER JOIN drug_indication ON molecule_dictionary.molregno = drug_indication.molregno INNER JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE molecule_dictionary.max_phase = 4 AND drug_indication.mesh_heading = 'chronic kidney disease' ORDER BY molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles, drug_indication.efo_id, drug_indication.efo_term, drug_indication.max_phase_for_ind
